const best = data && data.best ? data.best : null;
const points = data && Array.isArray(data.points) ? data.points : [];
const recent = data && Array.isArray(data.recent) ? data.recent : [];
const top = data && Array.isArray(data.top) ? data.top : [];
const archive = data && Array.isArray(data.archive) ? data.archive : [];
const threshold = Number(data && data.threshold) || 8;
const completed = Number(data && data.completed) || 0;
const anomalous = Number(data && data.anomalous) || 0;
const archived = Number(data && data.archived) || 0;

root.style.width = "100%";
root.style.height = "100%";
root.style.minHeight = "280px";
root.style.position = "relative";
root.style.overflow = "hidden";
root.style.background = "#ffffff";

root.innerHTML = `
<style>
  *{box-sizing:border-box}
  html,body{margin:0;background:#fff;color:#1d1d1f;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
  .a2{position:relative;height:100%;min-height:280px;overflow:hidden;background:#fff}
  canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
  .story{position:absolute;left:18px;top:15px;z-index:3;max-width:430px;pointer-events:none}
  .title{font-size:17px;font-weight:700;letter-spacing:-.02em;color:#1d1d1f}
  .sub{font-size:11px;color:#6e6e73;margin-top:3px;line-height:1.4}
  .scene-dots{position:absolute;right:10px;bottom:5px;z-index:4;display:flex;gap:1px;align-items:center}
  .scene-dot{position:relative;width:20px;height:20px;border:0;padding:0;border-radius:50%;background:transparent;cursor:pointer;appearance:none}
  .scene-dot::after{content:"";position:absolute;left:7px;top:7px;width:6px;height:6px;border-radius:50%;background:#d2d2d7;transition:background .12s ease}
  .scene-dot:hover::after{background:#86868b}
  .scene-dot.active::after{background:#1d1d1f}
  .scene-dot:focus-visible{outline:1px solid #86868b;outline-offset:-2px}
  .footer{position:absolute;left:18px;bottom:11px;z-index:3;color:#86868b;font-size:10px;pointer-events:none;letter-spacing:.01em}
</style>
<div class="a2">
  <canvas></canvas>
  <div class="story"><div class="title"></div><div class="sub"></div></div>
  <div class="footer"></div>
  <div class="scene-dots"><button class="scene-dot" type="button" aria-label="Show scene 1"></button><button class="scene-dot" type="button" aria-label="Show scene 2"></button><button class="scene-dot" type="button" aria-label="Show scene 3"></button></div>
</div>`;

const canvas = root.querySelector("canvas");
const ctx = canvas.getContext("2d");
const titleNode = root.querySelector(".title");
const subNode = root.querySelector(".sub");
const footerNode = root.querySelector(".footer");
const sceneDots = Array.from(root.querySelectorAll(".scene-dot"));
let width=1,height=1;

const suppliedInitialScene=(typeof initialScene!=="undefined"&&Number.isInteger(initialScene))?initialScene:0;
let currentScene=Math.max(0,Math.min(2,suppliedInitialScene));

function activateScene(index, notify=true){
  currentScene=Math.max(0,Math.min(sceneDots.length-1,index));
  sceneDots.forEach((dot,i)=>{
    const active=i===currentScene;
    dot.classList.toggle("active",active);
    dot.setAttribute("aria-pressed",active?"true":"false");
  });
  if(notify && project && project.id){
    window.parent.postMessage({type:"alinoe-visualization-scene",projectId:project.id,scene:currentScene},"*");
  }
}
sceneDots.forEach((dot,index)=>dot.addEventListener("click",()=>activateScene(index)));
activateScene(currentScene,false);

function resize(){
  const rect=canvas.getBoundingClientRect();
  const dpr=Math.min(window.devicePixelRatio||1,2);
  const w=Math.max(1,Math.round(rect.width*dpr));
  const h=Math.max(1,Math.round(rect.height*dpr));
  if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;width=w;height=h;}
  return dpr;
}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function smooth(v){const t=clamp(v,0,1);return t*t*(3-2*t);}
function setScene(index,title,sub,footer){
  titleNode.textContent=title;subNode.textContent=sub;footerNode.textContent=footer||"";
  sceneDots.forEach((dot,i)=>{
    const active=i===index;
    dot.classList.toggle("active",active);
    dot.setAttribute("aria-pressed",active?"true":"false");
  });
}
function line(x1,y1,x2,y2,stroke,widthPx,alpha=1,dash=[]){
  ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=stroke;ctx.lineWidth=widthPx;ctx.setLineDash(dash);
  ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.restore();
}
function text(value,x,y,size,dpr,color="#6e6e73",align="left",weight=400){
  ctx.save();ctx.fillStyle=color;ctx.textAlign=align;ctx.font=`${weight} ${size*dpr}px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif`;ctx.fillText(value,x,y);ctx.restore();
}
function formatZ(value){
  const v=Math.max(0,Number(value)||0);
  if(v<1000)return v.toFixed(2);
  if(v<1e6)return `${(v/1e3).toFixed(1)}k`;
  if(v<1e9)return `${(v/1e6).toFixed(1)}M`;
  if(v<1e12)return `${(v/1e9).toFixed(1)}B`;
  return v.toExponential(2);
}

function rotatePoint(p,angle){
  const x=(Number(p[0])||0)-7.5,y=(Number(p[1])||0)-7.5,z=(Number(p[2])||0)-7.5;
  const ca=Math.cos(angle),sa=Math.sin(angle),cb=Math.cos(-0.56),sb=Math.sin(-0.56);
  const x1=x*ca-z*sa,z1=x*sa+z*ca;
  const y2=y*cb-z1*sb,z2=y*sb+z1*cb;
  return [x1,y2,z2];
}
function project(p,dpr,angle){
  const q=rotatePoint(p,angle);
  const scale=Math.min(width,height)*0.031;
  const perspective=1/(1+q[2]*0.018);
  return [width*.53+q[0]*scale*perspective,height*.57-q[1]*scale*perspective,q[2]];
}
function cubeCorners(){
  const values=[0,15],c=[];for(const x of values)for(const y of values)for(const z of values)c.push([x,y,z]);return c;
}
const cubeEdges=[[0,1],[0,2],[0,4],[1,3],[1,5],[2,3],[2,6],[3,7],[4,5],[4,6],[5,7],[6,7]];

function drawEmpty(alpha,dpr){
  ctx.save();ctx.globalAlpha=alpha;
  text("waiting for the first validated experiment",width*.5,height*.55,12,dpr,"#86868b","center",500);
  ctx.restore();
}

function drawPhase(now,alpha,dpr){
  if(!best||!points.length){drawEmpty(alpha,dpr);return;}
  const angle=now*.00024;
  const corners=cubeCorners().map(p=>project(p,dpr,angle));
  ctx.save();ctx.globalAlpha=alpha;
  cubeEdges.forEach(([a,b])=>line(corners[a][0],corners[a][1],corners[b][0],corners[b][1],"#d2d2d7",.8*dpr,alpha,[3*dpr,4*dpr]));
  const projected=points.map((p,i)=>({p:project(p,dpr,angle),i})).sort((a,b)=>a.p[2]-b.p[2]);
  projected.forEach((item,index)=>{
    const depth=(item.p[2]+12)/24;
    const radius=(index%29===0?2.25:1.25)*dpr;
    ctx.globalAlpha=alpha*(0.22+0.62*clamp(depth,0,1));
    ctx.fillStyle=index%29===0?"#1d1d1f":"#6e6e73";
    ctx.beginPath();ctx.arc(item.p[0],item.p[1],radius,0,Math.PI*2);ctx.fill();
  });
  ctx.globalAlpha=alpha;
  text("0",corners[0][0]-8*dpr,corners[0][1]+12*dpr,9,dpr,"#86868b","right");
  text("15",corners[7][0]+7*dpr,corners[7][1]-6*dpr,9,dpr,"#86868b");
  const score=formatZ(best.score||0);
  text(`${best.generator_name||"generator"} · ${best.transform_name||"delay"} · τ ${best.tau}`,width-22*dpr,height-47*dpr,10,dpr,"#1d1d1f","right",600);
  text(`bits ${best.bit_offset}..${Number(best.bit_offset)+Number(best.bit_width)-1} · anomaly ${score} z`,width-22*dpr,height-30*dpr,9,dpr,"#86868b","right");
  ctx.restore();
}

function logScore(v){return Math.log10(1+Math.max(0,Number(v)||0));}
function drawSearch(alpha,dpr){
  if(!recent.length){drawEmpty(alpha,dpr);return;}
  const left=48*dpr,right=width-28*dpr,top=Math.max(78*dpr,height*.27),bottom=height-47*dpr;
  const w=Math.max(1,right-left),h=Math.max(1,bottom-top);
  const scores=recent.map(r=>Number(r.score)||0);
  const ymax=Math.max(logScore(threshold)*1.2,...scores.map(logScore),1);

  ctx.save();ctx.globalAlpha=alpha;
  for(let i=0;i<=4;i++){const y=top+h*i/4;line(left,y,right,y,"#eeeeef",1*dpr,alpha);}
  line(left,bottom,right,bottom,"#d2d2d7",1*dpr,alpha);
  const thresholdY=bottom-h*(logScore(threshold)/ymax);
  line(left,thresholdY,right,thresholdY,"#86868b",.9*dpr,alpha,[4*dpr,4*dpr]);
  text(`${threshold.toFixed(1)} z follow-up threshold`,right,thresholdY-6*dpr,9,dpr,"#86868b","right");

  let previous=null;
  recent.forEach((item,i)=>{
    const x=left+w*(recent.length<=1?0.5:i/(recent.length-1));
    const y=bottom-h*(logScore(item.score)/ymax);
    if(previous)line(previous[0],previous[1],x,y,"#d2d2d7",.9*dpr,alpha*.95);
    const interesting=Number(item.score)>=threshold;
    ctx.globalAlpha=alpha*(interesting?1:.62);ctx.fillStyle=interesting?"#1d1d1f":"#86868b";
    ctx.beginPath();ctx.arc(x,y,(interesting?2.8:1.8)*dpr,0,Math.PI*2);ctx.fill();
    previous=[x,y];
  });
  ctx.globalAlpha=alpha;
  text("anomaly score · log10 display",left,top-10*dpr,9,dpr,"#86868b");
  text(`${completed.toLocaleString()} experiments`,right,bottom+19*dpr,9,dpr,"#86868b","right");
  text(`${anomalous.toLocaleString()} threshold crossings · ${archived.toLocaleString()} archived leads`,right,top+12*dpr,10,dpr,"#1d1d1f","right",600);
  ctx.restore();
}

function drawEvidence(alpha,dpr){
  if(!best){drawEmpty(alpha,dpr);return;}
  const z=best.z||{};
  const rows=[
    ["occupancy",Number(z.occupancy)||0],
    ["collisions",Number(z.collisions)||0],
    ["recurrence",Number(z.recurrence)||0],
    ["correlation",Number(z.correlation)||0],
    ["axis bias",Number(z.axis_bias)||0],
  ];
  const left=42*dpr,right=Math.min(width*.61,width-190*dpr),top=Math.max(78*dpr,height*.27),rowH=29*dpr;
  const barLeft=left+86*dpr;
  const maxLog=Math.max(logScore(threshold)*1.15,...rows.map(row=>logScore(row[1])),1);
  ctx.save();ctx.globalAlpha=alpha;
  rows.forEach((row,i)=>{
    const y=top+i*rowH;
    text(row[0],left,y+10*dpr,9.5,dpr,"#6e6e73");
    line(barLeft,y+6*dpr,right,y+6*dpr,"#eeeeef",7*dpr,alpha);
    const fill=clamp(logScore(row[1])/maxLog,0,1);
    line(barLeft,y+6*dpr,barLeft+(right-barLeft)*fill,y+6*dpr,row[1]>=threshold?"#1d1d1f":"#86868b",7*dpr,alpha);
    text(`${formatZ(row[1])} z`,right+9*dpr,y+10*dpr,9,dpr,"#1d1d1f");
  });
  const thresholdX=barLeft+(right-barLeft)*clamp(logScore(threshold)/maxLog,0,1);
  line(thresholdX,top-7*dpr,thresholdX,top+rowH*4+18*dpr,"#d2d2d7",.8*dpr,alpha,[3*dpr,4*dpr]);
  text("bar length uses log10(1 + z)",left,top+rowH*5+7*dpr,8.5,dpr,"#86868b");

  const leads=archive.length?archive:top;
  const tableX=Math.max(width*.69,right+70*dpr);
  text(archive.length?"verified lead archive":"top anomaly leads",tableX,top-12*dpr,9,dpr,"#86868b","left",600);
  leads.slice(0,5).forEach((item,i)=>{
    const y=top+12*dpr+i*25*dpr;
    const name=`#${item.experiment_id} · ${item.generator_name}`;
    text(name,tableX,y,9,dpr,"#1d1d1f","left",i===0?600:400);
    text(`${formatZ(item.score||0)} z · τ ${item.tau}`,width-24*dpr,y,9,dpr,"#86868b","right");
  });
  text(`dominant metric: ${best.dominant||"—"}`,tableX,top+151*dpr,9,dpr,"#1d1d1f","left",600);
  text("z is a ranking heuristic against an iid uniform-bin reference",tableX,top+169*dpr,8.5,dpr,"#86868b","left");
  ctx.restore();
}

function frame(now){
  const dpr=resize();ctx.clearRect(0,0,width,height);ctx.fillStyle="#fff";ctx.fillRect(0,0,width,height);
  const scene=currentScene;
  if(scene===0){
    setScene(0,"1. Phase space","The strongest current lead, regenerated locally from the same generator, seed, transform and τ used by the ESP32 task.","16 × 16 × 16 phase-space bins · deterministic replay");
    drawPhase(now,1,dpr);
  }else if(scene===1){
    setScene(1,"2. Continuous search","Every point is one validated experiment. Crossing the threshold creates verification, neighbor, alternate-seed and control jobs.","no target iteration count · search continues until paused");
    drawSearch(1,dpr);
  }else{
    setScene(2,"3. Anomaly fingerprint","The five component scores explain why the current lead was flagged. Bars are logarithmic so one huge component cannot hide the others.","manual scene · approximate z-scores rank leads; follow-ups test persistence");
    drawEvidence(1,dpr);
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
